declare module '*.module.css' {
  const classes: Record<string, string>;
  export default classes;
}

/* -------------------------------------------------------------------------- */
/*  ПЕРЕМЕННЫЕ CSS В style                                                    */
/*                                                                            */
/*  Настройка компонентов идёт через свои свойства (--wrapper-bg,             */
/*  --container-max и прочие), и писать их хочется прямо в style.             */
/*  В типах React их нет: CSSProperties перечисляет только известные          */
/*  свойства, и литерал с «--…» отбивается проверкой лишних полей —           */
/*  замерено, TS2353 и на <div>, и на компоненте.                             */
/*                                                                            */
/*  Обходились приведением (`as CSSProperties`) и вычисляемым ключом          */
/*  (`['--x' as string]`), но оба прячут и настоящие опечатки в соседних      */
/*  свойствах. Одно объявление на проект решает это раз и навсегда:           */
/*  шаблонный ключ разрешает только имена, начинающиеся с двух дефисов,       */
/*  а всё остальное проверяется как прежде.                                   */
/* -------------------------------------------------------------------------- */

import 'react';

declare module 'react' {
    interface CSSProperties {
        [variable: `--${string}`]: string | number | undefined;
    }
}
